// PostgreSQL tenant registration flow.
// A new Business Owner receives a brand-new tenant_id and an empty business state.
// Run this transaction with a trusted DB/service connection, never with a client-supplied tenant_id.

async function registerBusinessOwner(pool, { email, passwordHash, displayName, businessName, slug, trialPlanId }) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // tenant_id is generated by PostgreSQL. It is never accepted from the browser.
    const tenantResult = await client.query(
      `INSERT INTO tenants (name, slug, status)
       VALUES ($1, $2, 'trial')
       RETURNING id`,
      [businessName, slug]
    );
    const tenantId = tenantResult.rows[0].id;

    // The first user is the Owner and is permanently bound to this tenant_id.
    await client.query(
      `INSERT INTO tenant_users
         (tenant_id, email, password_hash, display_name, role_code, status)
       VALUES ($1, $2, $3, $4, 'OWNER', 'active')`,
      [tenantId, email, passwordHash, displayName]
    );

    // Tenant-local configuration starts with safe defaults, not copied business data.
    await client.query(
      `INSERT INTO company_profiles (tenant_id, display_name)
       VALUES ($1, $2)`,
      [tenantId, businessName]
    );

    await client.query(
      `INSERT INTO tenant_tax_settings (tenant_id)
       VALUES ($1)`,
      [tenantId]
    );

    // Create only the tenant's own role definitions. No users or business records
    // from another tenant are copied or reused.
    await client.query(
      `INSERT INTO tenant_roles (tenant_id, code, name)
       VALUES ($1, 'OWNER', 'Owner'),
              ($1, 'MANAGER', 'Manager'),
              ($1, 'CASHIER', 'Cashier')`,
      [tenantId]
    );

    // Optional subscription metadata is created for this tenant only.
    if (trialPlanId) {
      await client.query(
        `INSERT INTO subscriptions (tenant_id, plan_id, status)
         VALUES ($1, $2, 'trialing')`,
        [tenantId, trialPlanId]
      );
    }

    // IMPORTANT: Do not INSERT any sales, purchases, labour, stock, cash-book,
    // daily-book, khata, invoice, or other business transactions here.
    // Those tables must start with zero rows for this tenant_id.

    await client.query('COMMIT');
    return { tenantId };
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }
}

module.exports = { registerBusinessOwner };
